package com.pixilife.android;import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.graphics.Color;import android.os.*;import android.provider.CalendarContract;import android.widget.*;import java.util.*;
public class CalendarActivity extends Activity {private LinearLayout list;@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(25,25,25,25);r.setBackgroundColor(Color.rgb(7,11,17));TextView h=t("CALENDARIO DE PIXI",24);r.addView(h);ScrollView s=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);s.addView(list);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);load();}private void load(){list.removeAllViews();if(checkSelfPermission(Manifest.permission.READ_CALENDAR)!=PackageManager.PERMISSION_GRANTED){list.addView(t("Falta permiso de calendario",16));return;}long now=System.currentTimeMillis(),end=now+30L*86400000L;String[] cols={CalendarContract.Instances.EVENT_ID,CalendarContract.Instances.TITLE,CalendarContract.Instances.BEGIN,CalendarContract.Instances.END};android.net.Uri.Builder b=CalendarContract.Instances.CONTENT_URI.buildUpon();ContentUris.appendId(b,now);ContentUris.appendId(b,end);try(Cursor c=getContentResolver().query(b.build(),cols,null,null,CalendarContract.Instances.BEGIN)){while(c!=null&&c.moveToNext()){long id=c.getLong(0);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.addView(t(c.getString(1)+"\n"+new Date(c.getLong(2)),16));Button d=new Button(this);d.setText("Eliminar evento");d.setOnClickListener(v->{if(checkSelfPermission(Manifest.permission.WRITE_CALENDAR)==PackageManager.PERMISSION_GRANTED)getContentResolver().delete(ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI,id),null,null);load();});row.addView(d);list.addView(row);}}catch(Exception e){list.addView(t("Error: "+e.getMessage(),16));}}private TextView t(String x,int z){TextView t=new TextView(this);t.setText(x);t.setTextColor(Color.WHITE);t.setTextSize(z);t.setPadding(8,10,8,10);return t;}}
